insert into public.question_bank (code, lesson_id, type, level, content, answer_number, tolerance, unit, explanation, formula, remember, points, source, status, sort_order) values ('B17-05', (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 17), 'true_false', 'hieu', 'Xét các phát biểu về thuỷ điện.', null, 0, null, 'Thuỷ điện là năng lượng tái tạo nhưng vẫn có tác động môi trường.', null, null, 1, 'PHYSICS AI – câu hỏi mẫu', 'published', 5) on conflict (code) do update set lesson_id = excluded.lesson_id, type = excluded.type, level = excluded.level, content = excluded.content, answer_number = excluded.answer_number, tolerance = excluded.tolerance, unit = excluded.unit, explanation = excluded.explanation, formula = excluded.formula, remember = excluded.remember, sort_order = excluded.sort_order;
insert into public.question_subitems (question_id, label, content, is_true, explanation) values ((select id from public.question_bank where code = 'B17-05'), 'a', 'Năng lượng của dòng nước có nguồn gốc từ năng lượng Mặt Trời (vòng tuần hoàn của nước).', true, 'Mặt Trời làm nước bay hơi, tạo mưa đổ về hồ chứa.') on conflict (question_id, label) do update set content = excluded.content, is_true = excluded.is_true, explanation = excluded.explanation;
insert into public.question_subitems (question_id, label, content, is_true, explanation) values ((select id from public.question_bank where code = 'B17-05'), 'b', 'Nhà máy thuỷ điện biến đổi thế năng của nước thành điện năng (thông qua động năng làm quay tua-bin).', true, 'Thế năng → động năng → điện năng.') on conflict (question_id, label) do update set content = excluded.content, is_true = excluded.is_true, explanation = excluded.explanation;
insert into public.question_subitems (question_id, label, content, is_true, explanation) values ((select id from public.question_bank where code = 'B17-05'), 'c', 'Khi vận hành, nhà máy thuỷ điện thải nhiều khí CO₂ như nhà máy nhiệt điện than.', false, 'Thuỷ điện không đốt nhiên liệu nên hầu như không thải CO₂ khi vận hành.') on conflict (question_id, label) do update set content = excluded.content, is_true = excluded.is_true, explanation = excluded.explanation;
insert into public.question_subitems (question_id, label, content, is_true, explanation) values ((select id from public.question_bank where code = 'B17-05'), 'd', 'Xây dựng hồ thuỷ điện không ảnh hưởng gì đến hệ sinh thái.', false, 'Có thể làm ngập rừng, thay đổi dòng chảy, ảnh hưởng sinh vật.') on conflict (question_id, label) do update set content = excluded.content, is_true = excluded.is_true, explanation = excluded.explanation;
insert into public.question_bank (code, lesson_id, type, level, content, answer_number, tolerance, unit, explanation, formula, remember, points, source, status, sort_order) values ('B17-06', (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 17), 'short_answer', 'van_dung', 'Mỗi giây có 1 000 kg nước chảy từ độ cao 50 m xuống làm quay tua-bin, hiệu suất 80%. Công suất điện thu được là bao nhiêu kW?', 400, 0.5, 'kW', 'Công trọng lực mỗi giây: A = 10·m·h = 10·1 000·50 = 500 000 J → P = 0,8·500 000 = 400 000 W = 400 kW.', 'P = η·10·m·h/t', null, 1, 'PHYSICS AI – câu hỏi mẫu', 'published', 6) on conflict (code) do update set lesson_id = excluded.lesson_id, type = excluded.type, level = excluded.level, content = excluded.content, answer_number = excluded.answer_number, tolerance = excluded.tolerance, unit = excluded.unit, explanation = excluded.explanation, formula = excluded.formula, remember = excluded.remember, sort_order = excluded.sort_order;
insert into public.question_bank (code, lesson_id, type, level, content, answer_number, tolerance, unit, explanation, formula, remember, points, source, status, sort_order) values ('B17-07', (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 17), 'short_answer', 'van_dung', 'Một hệ thống pin Mặt Trời công suất 5 kW hoạt động trung bình 4 giờ đủ nắng mỗi ngày. Điện năng tạo ra mỗi ngày là bao nhiêu kWh?', 20, 0.01, 'kWh', 'W = P·t = 5 kW · 4 h = 20 kWh.', 'W = P·t', null, 1, 'PHYSICS AI – câu hỏi mẫu', 'published', 7) on conflict (code) do update set lesson_id = excluded.lesson_id, type = excluded.type, level = excluded.level, content = excluded.content, answer_number = excluded.answer_number, tolerance = excluded.tolerance, unit = excluded.unit, explanation = excluded.explanation, formula = excluded.formula, remember = excluded.remember, sort_order = excluded.sort_order;
